using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpHttpServer;

[McpServerResourceType]
public static class ConfigResources
{
    private static readonly Dictionary<string, object> AppConfig = new()
    {
        ["appName"] = "MyService",
        ["version"] = "1.0.0",
        ["maxRetries"] = 3,
        ["timeoutSeconds"] = 30,
        ["features"] = new Dictionary<string, bool>
        {
            ["darkMode"] = true,
            ["betaFeatures"] = false,
        }
    };

    [McpServerResource(UriTemplate = "config://app/settings",
        Name = "app-settings",
        Title = "Application Settings",
        MimeType = "application/json")]
    [Description("Returns the current application configuration as JSON.")]
    public static string GetAppSettings()
    {
        return JsonSerializer.Serialize(AppConfig, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/settings/{section}",
        Name = "app-settings-section",
        Title = "Application Settings Section",
        MimeType = "application/json")]
    [Description("Returns a specific section of the application configuration.")]
    public static string GetAppSettingsSection(string section)
    {
        if (AppConfig.TryGetValue(section, out var value))
        {
            return JsonSerializer.Serialize(value, new JsonSerializerOptions { WriteIndented = true });
        }

        return JsonSerializer.Serialize(new { error = $"Section '{section}' not found" });
    }
}

